 let transport=null,predictor=null,pingMs=null,runtime={contracts:{configured:false,enabled:false,symbol:'GAME',decimals:9,lockSeconds:604800}},tokenState={levels:Array(12).fill(1),locked:Array(12).fill('0'),positions:[],refunds:[]},walletAddress=null,marketFrame=null,marketTimer=null,progression='staking',rewardData=null,pendingCommands=[],matchAsset='token',capturedLanes=new Set();
 const saveLocal=()=>{try{localStorage.setItem('clashlings-practice',JSON.stringify({name:profile.name,deck:profile.deck,sound,history:practiceHistory}));}catch{}};
 root.innerHTML=`<div class="app-shell"><header class="topbar"><button class="brand" data-page="battle" aria-label="Clashlings home"><span class="brand-mark">${icon('crown')}</span><span><b>CLASHLINGS</b><small>MARKET ARENA</small></span></button><nav class="desktop-nav" aria-label="Main navigation"><button data-page="battle" class="active">${icon('swords')}Battle</button><button data-page="cards">${icon('cards')}Collection</button><button data-page="forge">${icon('forge')}Upgrades</button><button data-page="ranks">${icon('rank')}Leaderboard</button><button data-page="rewards">${icon('coin')}Rewards</button></nav><div class="top-actions"><button class="wallet-connect" data-action="connect-wallet"><i></i><span id="wallet-label">Connect wallet</span></button><button class="balance-chip" data-page="profile">${icon('coin')}<span><b id="credit-top">0</b><small>GAME earned</small></span></button><button class="trainer-chip" data-page="profile">${sprite(1)}<span id="trainer-top">Trainer</span></button><button class="icon-button" id="sound-btn" aria-label="Toggle sound">${icon('sound')}</button><button class="icon-button" data-action="help" aria-label="How to play">${icon('help')}</button></div></header><div class="page-heading"><div class="page-heading-title"><span class="page-icon" id="page-icon">${icon('swords')}</span><h1 id="page-title">Battle</h1><span class="page-context" id="page-context">Verdant Crossing</span></div><div class="page-meta" id="page-meta"></div></div><main id="main-content"></main><nav class="mobile-nav" aria-label="Mobile navigation"><button data-page="battle">${icon('swords')}Battle</button><button data-page="cards">${icon('cards')}Cards</button><button data-page="forge">${icon('forge')}Upgrade</button><button data-page="ranks">${icon('rank')}Ranks</button><button data-page="rewards">${icon('coin')}Rewards</button><button data-page="profile">${icon('user')}Trainer</button></nav><footer class="site-footer"><span>CLASHLINGS <b>·</b> Built for the next great rivalry.</span><span>GAME token arena</span></footer></div><div id="toast" role="status" aria-live="polite"></div><div id="modal-root"></div>`;
 const $=s=>root.querySelector(s);
 function updateLayout(){const shell=$('.app-shell'),layout=battleLayout(window.innerWidth,window.innerHeight,playing);shell.dataset.dock=layout.dock;shell.dataset.sidebar=String(layout.sidebar);shell.dataset.immersive=String(layout.immersive);}
 window.addEventListener('resize',updateLayout);
