 function tone(freq=500,dur=.08){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),v=audio.createGain();o.type='triangle';o.frequency.value=freq;v.gain.setValueAtTime(.06,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}catch{}}
 function updateHeader(){if(disposed)return;$('#credit-top').textContent=(profile.tokenEarned||0).toLocaleString();$('#trainer-top').textContent=profile.name;$('#sound-btn').classList.toggle('muted',!sound);$('#wallet-label').textContent=walletAddress?walletAddress.slice(0,4)+'…'+walletAddress.slice(-4):'Connect wallet';$('.wallet-connect').classList.toggle('connected',!!walletAddress);}
 function modal(html,onReady,options={}){if(disposed)return;const previous=$('#modal-root .modal')?modalFocus:document.activeElement;clearModal();modalFocus=previous;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${options.className||''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="modal-close icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${html}</section></div>`;$('.app-shell').inert=true;document.body.classList.add('modal-open');const title=$('#modal-root h2');if(title)title.id='modal-title';modalCb=onReady;const cleanup=onReady?.();if(typeof cleanup==='function')modalCleanup=cleanup;const target=$('#modal-root input, #modal-root button:not(.modal-close), #modal-root a')||$('#modal-root .modal');target?.focus({preventScroll:true});}
 function clearModal(restoreFocus=false){modalCleanup?.();modalCleanup=null;$('#modal-root').innerHTML='';modalCb=null;$('.app-shell').inert=false;document.body.classList.remove('modal-open');if(restoreFocus)(modalFocus?.isConnected?modalFocus:$('.brand'))?.focus({preventScroll:true});}
 function closeModal(){if(queueId){cancelQueue();return;}clearModal(true);}
 async function call(path,body){const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(9000)});let data;try{data=await response.json();}catch{throw new Error('Connection interrupted. Try again.');}if(!response.ok)throw Object.assign(new Error(data.error||'Try again shortly.'),{status:response.status});return data;}
 async function refresh(){if(!account)return;const data=await call('profile');if(disposed)return;profile=data;walletAddress=data.wallet||walletAddress;activeHold=data.activeMatch;updateHeader();return data;}
 function onboarding(needsSignIn=false){modal(`<div class="modal-art">${sprite(0)}</div><span class="eyebrow">YOUR ADVENTURE STARTS HERE</span><h2>Meet your new squad.</h2><p>Build a squad of 12 market-inspired fighters. Connect a Solana wallet to sign in. New accounts start with no GAME — you earn it by winning token battles.</p><button class="button primary wide" data-action="connect-wallet">Connect Solana wallet</button>${needsSignIn?'':'<form id="trainer-form"><label for="name-input">Trainer name</label><input id="name-input" maxlength="16" value="'+esc(profile.name==='Trainer'?'':profile.name)+'" placeholder="Choose a name" required autocomplete="nickname"><button class="button primary wide" type="submit">Create trainer '+icon('arrow')+'</button></form>'}<button class="text-button wide" data-action="practice-guest">Try free practice first</button><small class="fineprint">Practice is free. Ranked rewards are GAME won from token fights.</small>`,()=>{const form=$('#trainer-form');form?.addEventListener('submit',async e=>{e.preventDefault();const btn=form.querySelector('button');btn.disabled=true;try{profile=await call('profile',{name:$('#name-input').value,deck:profile.deck});account=true;activeHold=null;saveLocal();clearModal();updateHeader();renderPage();toast('Trainer ready. Win GAME in the token arena.');tone(720,.16);}catch(error){toast(error.message);if(error.status===401)onboarding(true);}finally{btn.disabled=false;}});});}
 let render=null;
 function battleHTML(){return `<div class="battle-layout"><aside class="left-column"><section class="welcome-card"><span class="eyebrow">YOUR ASSETS. YOUR ARENA.</span><h2>Market moves.<br>Squad <em>strikes.</em></h2>${sprite(0,'hero-sprite')}<span class="hero-sticker">BITCOIN BULL ENERGY</span><p>Build your token squad.<br>Capture enemy territory.<br>Battle with the market.</p></section><section class="panel deck-panel"><div class="panel-heading"><h3>Your battle deck</h3><button class="text-button" data-page="cards">Edit ${icon('arrow')}</button></div><div class="mini-deck">${profile.deck.map(id=>card(CARDS[id],squadLevels()[id],'mini',`data-card="${id}"`)).join('')}</div><div class="deck-average">${icon('bolt')} ${(profile.deck.reduce((a,i)=>a+CARDS[i].cost,0)/8).toFixed(1)} average elixir <span>8 / 8</span></div></section></aside><section class="arena-section"><div class="arena-frame"><div class="battle-score"><span class="opponent-name" id="opponent-name">${icon('shield')}Sage Bot</span><span class="timer" id="timer">2:30</span><span class="score-label" id="score">0 : 0</span></div><div class="canvas-wrap"><div class="scene-toolbar"><span class="scene-badge"><i></i><b id="scene-mode">LIVE 3D</b></span><button class="market-info" data-action="market" id="market-info">MARKET · NEUTRAL</button><div class="scene-actions" role="group" aria-label="3D camera controls"><button data-camera="left" title="Orbit left" aria-label="Orbit camera left">↶</button><button data-camera="right" title="Orbit right" aria-label="Orbit camera right">↷</button><button data-camera="view" title="Switch tactical / cinematic camera" aria-label="Switch tactical and cinematic view">View</button><button data-camera="zoom" title="Toggle close view" aria-label="Toggle camera zoom">+</button><button data-camera="reset" title="Reset camera" aria-label="Reset camera">⌂</button></div></div><canvas id="arena" width="600" height="760" aria-label="3D tower battle arena. Use camera controls to orbit the battlefield. Use the creature buttons and deploy left or right buttons to play."></canvas><div class="arena-overlay" id="arena-overlay">${icon('crown')}<div><strong>Your squad is ready.</strong><p>Choose a battle mode and start playing.</p></div></div><div class="pause-overlay" id="pause-overlay" hidden><h2>Take a breath.</h2><button class="button primary" data-action="pause">Resume practice</button></div></div><div class="battle-control"><div class="hand-heading"><span id="hand-hint">Your starting hand</span><button class="text-button" id="pause-btn" data-action="pause" hidden>${icon('pause')}<span>Pause</span></button><button class="text-button" id="surrender-btn" data-action="surrender" aria-label="Leave battle" hidden>${icon('close')}<span>Leave</span></button></div><div class="hand-row"><div class="hand" id="hand"></div><div class="next-card"><span>NEXT</span><div id="next-sprite"></div></div></div><div class="elixir-row"><span class="elixir-label">${icon('bolt')}<b id="elixir-value">5.0</b></span><div class="elixir-bar"><span id="elixir-fill"></span>${Array(9).fill('<i></i>').join('')}</div><span id="elixir-rate">ELIXIR</span></div><div class="lane-controls" id="lane-controls" hidden><button data-action="left-lane">Deploy left</button><span>1–4 to pick</span><button data-action="right-lane">Deploy right</button></div></div></div><div class="arena-caption">${icon('shield')} Destroy the central tower, or lead when the timer ends.</div></section><aside class="right-column"><section class="panel play-panel"><div class="panel-heading"><h3>Choose your battle</h3>${icon('swords')}</div><div class="mode-tabs"><button data-mode="practice" class="${mode==='practice'?'active':''}">Practice</button><button data-mode="token" class="${mode==='token'?'active':''}">Tokens</button></div><div id="mode-content">${modeHTML()}</div></section><section class="panel tip-panel"><span class="tip-badge">THE SMART PLAY</span><h3>Big tanks. Little backup.</h3><div class="tip-creatures">${sprite(2)}${sprite(1)}</div><p>Send Etherion first, then Solstrider. The tank takes the hits while your ranged creature fires safely.</p><button class="text-button" data-card="2">Meet Etherion ${icon('arrow')}</button></section><section class="upgrade-promo"><span>${icon('forge')}</span><div><h3>Grow your favorites.</h3><p>Stake tokens. Grow your squad.</p></div><button class="icon-button" data-page="forge" aria-label="Open creature upgrades">${icon('arrow')}</button></section><p class="access-note">Online battles need two trainers with access to this site. Practice is always ready.</p></aside></div>`;}
 function modeHTML(){if(mode==='token')return tokenModeHTML();return `<span class="mode-eyebrow">WARM UP YOUR STRATEGY</span><h3>Meet Sage Bot.</h3><p>Practice uses your GAME staking levels. Nothing is at stake.</p><div class="difficulty-pick"><button data-difficulty="easy" class="${difficulty==='easy'?'active':''}">Rookie</button><button data-difficulty="normal" class="${difficulty==='normal'?'active':''}">Challenger</button></div><button class="button primary wide" data-action="practice">${icon('swords')}Start practice</button>`;}
 function renderPage(){if(disposed)return;render?.dispose?.();render=null;const main=$('#main-content');updateLayout();$('.app-shell').dataset.page=page;$('.app-shell').classList.toggle('battle-screen',page==='battle');$('.app-shell').dataset.playing=String(playing);document.body.classList.toggle('in-battle',page==='battle');updateHeader();root.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#page-title').textContent=({battle:'Battle',cards:'Collection',forge:'Upgrades',ranks:'Leaderboard',profile:'Trainer',rewards:'Rewards'})[page];const pageIcon={battle:'swords',cards:'cards',forge:'forge',ranks:'rank',profile:'user',rewards:'coin'}[page];$('#page-icon').innerHTML=icon(pageIcon);$('#page-context').textContent=({battle:'Verdant Crossing',cards:'Build your squad',forge:'Grow your favorites',ranks:'The Clashlings League',profile:'GAME, staking, history',rewards:'Earn GAME in battle'})[page];$('#page-meta').innerHTML=page==='battle'?`<span class="arena-status" id="arena-status"><i></i>${playing?(online?'TOKEN BATTLE':'PRACTICE'):'READY TO PLAY'}</span>`:page==='cards'?icon('cards')+'12 / 12 unlocked':page==='forge'?icon('forge')+'Token staking':page==='ranks'?icon('coin')+(account?(profile.tokenEarned||0)+' GAME earned':'Token rankings'):page==='profile'?icon('coin')+(profile.tokenEarned||0)+' GAME earned':icon('coin')+'Fight earnings';main.scrollTop=0;
  if(page==='rewards'){main.innerHTML=rewardsHTML();loadRewards();}
  else if(page==='battle'){main.innerHTML=battleHTML();render=renderer($('#arena'));bindArena();hudKey='';hud();$('#arena-overlay').hidden=playing;$('#pause-btn').hidden=!playing||online;$('#surrender-btn').hidden=!playing;$('#lane-controls').hidden=!playing;render.draw(g,{side,active:playing,selected});}
  else if(page==='cards'||page==='forge'){const displayLevels=page==='forge'?tokenState.levels:squadLevels('practice');main.innerHTML=`<section class="collection-intro"><p>${page==='forge'?'Stake GAME to unlock character levels. Each level adds 10% of base health and damage in practice and the token arena.':'All 12 creatures are yours. Choose eight for your deck and build a squad that plays your way.'}</p></section>${page==='forge'?`<div class="progression-tabs"><span>Stake the game token to unlock character levels for every battle.</span></div>`:''}${page==='cards'?`<section class="deck-builder panel"><div class="panel-heading"><h3>Battle deck <small>Click a slot to replace it</small></h3><button class="text-button" data-action="reset-deck">Starter deck</button></div><div class="builder-deck">${profile.deck.map((id,i)=>card(CARDS[id],squadLevels()[id],'mini',`data-deck-slot="${i}"`)).join('')}</div></section><div class="collection-tools"><h3>Find your favorites</h3><div class="filter-tabs">${['all','ground','air'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f==='all'?'All creatures':f==='ground'?'Ground crew':'Air squad'}</button>`).join('')}</div></div>`:''}<div class="collection-grid">${CARDS.filter(c=>page==='forge'||filter==='all'||(filter==='air'?c.air:!c.air)).map(c=>`<article class="collection-item">${card(c,displayLevels[c.id],'large',`data-card="${c.id}"`)}<div class="collection-info"><div class="creature-role"><span>${c.role}</span><div class="mini-stats"><span>${stats(c.id,displayLevels[c.id]).hp}<small>HP</small></span><span>${stats(c.id,displayLevels[c.id]).dmg}<small>DMG</small></span></div></div>${page==='forge'?`<button class="button ${displayLevels[c.id]>=5?'secondary':'primary'}" data-upgrade="${c.id}">${displayLevels[c.id]>=5?'View stake / withdraw':icon('forge')+'Stake · '+stakeRequirement(c.id,displayLevels[c.id]+1).toLocaleString()}</button><small class="stake-note">${displayLevels[c.id]>=5?'Withdraw from this card after the 1-day lock':'Total stake for next level · '+esc(runtime.contracts.symbol)}</small>`:`<button class="text-button" data-card="${c.id}">Creature details ${icon('arrow')}</button>`}</div></article>`).join('')}</div>`;}
  else if(page==='profile'){main.innerHTML=profileHTML();renderTokenProfile();if(account)call('ledger').then(d=>{if(page!=='profile'||disposed)return;paintLedger(d.entries||[]);}).catch(e=>{if($('#credit-history'))$('#credit-history').textContent=e.message;});}
  else if(page==='ranks'){main.innerHTML=ranksHTML();if(account)call('ranks').then(d=>{if(page!=='ranks'||disposed)return;paintRanks(d.players||[]);}).catch(e=>{if($('#rank-list'))$('#rank-list').textContent=e.message;});}
 }
 function details(id){const c=CARDS[id],lv=page==='forge'?(tokenState.levels[id]||1):squadLevels()[id],s=stats(id,lv);modal(`<div class="detail-art" style="--card-color:${c.color}">${sprite(id)}<span class="cost">${c.cost}</span></div><span class="eyebrow">${c.symbol} ${TOKENS[id].asset==='equity'?'EQUITY':'CRYPTO'} · ${c.role.toUpperCase()}</span><h2>${c.name}<span class="level-pill">LV. ${lv}</span></h2><p>${c.desc}</p><p class="market-detail">Live price moves modify damage every ${MARKET_INTERVAL} seconds: 6× sensitivity, capped at −15% / +15%. ${TOKENS[id].asset==='equity'?'NVDA is an equity reference; stale or closed-market quotes stay neutral.':''}</p><div class="creature-stats"><span>Health<b>${s.hp}</b></span><span>Damage<b>${s.dmg}</b></span><span>Speed<b>${c.speed}</b></span><span>Attack<b>${c.air?'Air & ground':c.airHit?'Air & ground':'Ground'}</b></span></div>${profile.deck.includes(id)?'<span class="in-deck">'+icon('check')+'In your battle deck</span>':`<button class="button secondary wide" data-add-card="${id}">Add to battle deck ${icon('plus')}</button>`}<button class="button primary wide" data-upgrade="${id}">View staking levels</button><small class="fineprint">${lv<5?'Next level: '+stats(id,lv+1).hp+' health · '+stats(id,lv+1).dmg+' damage.':'Maximum staking level. Ready for the arena.'}</small>`);}
 function replacement(slot,newId){modal(`<span class="eyebrow">BUILD YOUR BATTLE DECK</span><h2>${newId===undefined?'Choose a replacement.':'Choose a slot to replace.'}</h2><div class="replace-grid">${(newId===undefined?CARDS.filter(c=>!profile.deck.includes(c.id)):profile.deck.map(id=>CARDS[id])).map((c,i)=>card(c,squadLevels('practice')[c.id],'mini',newId===undefined?`data-replace-slot="${slot}" data-replace-id="${c.id}"`:`data-replace-slot="${i}" data-replace-id="${newId}"`)).join('')}</div>`);}
 async function saveDeck(next){if(playing||queueId){toast('Finish your battle first.');return;}try{if(account)profile=await call('profile',{name:profile.name,deck:next});else profile.deck=next;saveLocal();clearModal();renderPage();toast('Your battle deck is ready.');}catch(e){toast(e.message);}}
