 async function loadTokenState(){if(!account)return;try{tokenState=await call('token/status');walletAddress=tokenState.wallet||walletAddress;updateHeader();if(page==='forge')renderPage();if(page==='profile')renderTokenProfile();if(page==='battle'&&!playing){paintMiniDeck();if($('#mode-content'))$('#mode-content').innerHTML=modeHTML();}}catch{}}
 function squadLevels(){return tokenState.levels||Array(12).fill(1);}
 function paintMiniDeck(){const el=$('.mini-deck');if(!el)return;el.innerHTML=profile.deck.map(id=>card(CARDS[id],squadLevels()[id],'mini',`data-card="${id}"`)).join('');}
 function tokenModeHTML(){const cfg=runtime.contracts,levels=squadLevels('token'),bench=CARDS.filter(c=>(levels[c.id]||1)>1&&!profile.deck.includes(c.id));return `<span class="mode-eyebrow">SOLANA TOKEN ARENA</span><h3>Your squad. Real stakes.</h3><p>Both wallets lock an equal GAME entry. Winner takes the pot. Your staking levels apply here.</p><div class="token-launch-status${cfg.enabled?' live':''}"><i></i>${cfg.enabled?'Token arena is live':'Token arena needs the live match service'}</div><div class="token-squad">${profile.deck.map(id=>`<span><b>LV. ${levels[id]||1}</b>${esc(CARDS[id].name)}</span>`).join('')}</div>${bench.length?`<p class="token-bench">Staked off the deck: ${bench.map(c=>`<button class="text-button" data-add-card="${c.id}">${esc(c.name)} LV. ${levels[c.id]}</button>`).join(' ')}. Swap one into your eight to fight with those levels.</p>`:''}<div class="stake-pick">${[25,50,100].map(n=>`<button data-stake="${n}" class="${stake===n?'active':''}">${n}</button>`).join('')}</div><div class="pot-summary"><span>Entry<b>${stake} ${esc(cfg.symbol)}</b></span><span>Winner's pot<b>${stake*2} ${esc(cfg.symbol)}</b></span></div><button class="button primary wide" data-action="token-ranked" ${!cfg.enabled?'disabled':''}>Find a token rival</button><div class="token-room-actions"><button class="text-button" data-action="token-create" ${!cfg.enabled?'disabled':''}>Create room</button><button class="text-button" data-action="token-join" ${!cfg.enabled?'disabled':''}>Join room</button></div><small class="fineprint">${cfg.enabled?'Approve the escrow in your wallet. Winner takes the pot in GAME. Leaderboard ranks by GAME earned from fights.':'Start pnpm realtime:dev next to the site, then refresh.'} Token funds are held by the game contract.</small>`;}
 function walletModal(){
  if(playing||queueId){toast('Finish or cancel your battle before changing wallets.');return;}walletChoices=availableWallets();
  modal(`<span class="eyebrow">SOLANA WALLET</span><h2>${walletAddress?'Your wallet. Your trainer.':'Connect to the arena.'}</h2><p>Sign a message to prove this wallet is yours. Signing in does not transfer tokens.${runtime.contracts.chain&&runtime.contracts.chain!=='solana:mainnet'?' This arena uses '+esc(runtime.contracts.chain)+' — switch Phantom to that network first.':''}</p>${walletAddress?`<div class="wallet-address" title="${esc(walletAddress)}">${esc(walletAddress)}</div>`:''}<div class="wallet-options">${walletChoices.map((w,i)=>`<button class="button secondary wide" data-wallet-index="${i}">${esc(w.name)}</button>`).join('')||'<p class="empty-state">Open this site in a Solana wallet browser, or connect through WalletConnect.</p>'}<button class="button primary wide" data-action="wallet-relay" ${!runtime.walletConnectProjectId?'disabled':''}>WalletConnect · QR / mobile</button></div>${!runtime.walletConnectProjectId?'<small class="fineprint">WalletConnect QR will be available at launch. Installed Solana wallets can sign in now.</small>':''}${walletAddress?'<button class="text-button wide" data-action="wallet-disconnect">Sign out of wallet</button>':''}`);
 }
 async function loginWallet(index){
  try{
   let address;if(index==='relay'){modal('<span class="eyebrow">WALLETCONNECT</span><h2>Connect your wallet.</h2><div id="wallet-qr" class="wallet-qr"><p>Preparing a secure connection…</p></div>');address=await connectRelay(runtime.walletConnectProjectId,async uri=>{const {default:QR}=await import('qrcode'),src=await QR.toDataURL(uri,{width:280,margin:2});const container=$('#wallet-qr');if(container)container.innerHTML=`<img src="${src}" alt="WalletConnect pairing QR code"><p>Scan with your Solana wallet.</p><a class="button secondary wide" href="${esc(uri)}">Open wallet app</a>`;},runtime.contracts.chain);}
   else{const selectedWallet=walletChoices[index]?.wallet;if(!selectedWallet)throw new Error('Select a wallet again.');address=await connectStandard(selectedWallet,runtime.contracts.chain);}
   modal('<span class="eyebrow">VERIFY YOUR WALLET</span><h2>Approve the sign-in message.</h2><p>Check the website address in your wallet. This signature authenticates your trainer; it does not move funds.</p>');
   const challenge=await call('auth/wallet/challenge',{address}),signature=await signLogin(challenge);await call('auth/wallet/verify',{id:challenge.id,signature});walletAddress=address;clearModal();
   try{const data=await call('profile');profile=data;account=true;activeHold=data.activeMatch;await loadTokenState();renderPage();toast('Wallet verified. Welcome back.');}catch(e){if(e.status===409){account=false;onboarding(false);}else throw e;}updateHeader();
  }catch(e){toast(e.message||'Wallet connection was cancelled.');if(!walletAddress)clearModal();}
 }
 async function logoutWallet(){try{await call('auth/wallet/logout',{});await disconnectWallet();walletAddress=null;account=false;tokenState={levels:Array(12).fill(1),locked:Array(12).fill('0'),positions:[],refunds:[]};try{profile=await call('profile');account=true;}catch{profile={...profile,balance:0,levels:Array(12).fill(1),wins:0,losses:0,trophies:0,tokenEarned:0};}clearModal();renderPage();toast('Wallet signed out.');}catch(e){toast(e.message);}}
 function marketModal(){const prices=marketFrame?.prices||[];modal(`<span class="eyebrow">MARKET ENGINE</span><h2>When markets move, fighters respond.</h2><p>Each match locks its starting prices. Every ${MARKET_INTERVAL} seconds, damage changes by 6× the price move, capped at −15% to +15%.</p><div class="market-formula">Damage = clamp(1 + price move × 6, 0.85, 1.15)</div><div class="market-table">${TOKENS.map((t,i)=>{const price=prices[i],mult=g.market?.multipliers?.[i]??1,status=playing?g.market?.status?.[i]:price?.status,percent=Math.round((mult-1)*100);return `<div><b>${t.symbol}<small>${t.asset==='equity'?'Equity reference':'Crypto reference'}</small></b><span>${price?.status==='live'?'$'+price.price.toLocaleString(undefined,{maximumSignificantDigits:6}):'No live quote'}<small>${status==='live'?(marketFrame?.source==='Pyth'?'Pyth':'Public')+' · '+new Date((price?.publishTime||0)*1000).toLocaleTimeString():status==='no-baseline'?'No match baseline · neutral':status==='unconfigured'?'Feed awaiting connection':'Unavailable / stale · neutral'}</small></span><strong class="${percent>0?'positive':percent<0?'negative':''}">${percent>0?'+':''}${percent}%</strong></div>`;}).join('')}</div><small class="fineprint">Missing or stale quotes stay at 1.00×. A missing match baseline is never reset mid-battle. NVDA is an equity reference and can be neutral outside market hours. Character themes do not imply asset sponsorship.</small>`);}
 function formatUnits(units,decimals=runtime.contracts.decimals){try{const n=BigInt(units),scale=10n**BigInt(decimals),whole=n/scale,fraction=(n%scale).toString().padStart(decimals,'0').replace(/0+$/,'');return whole.toLocaleString()+(fraction?'.'+fraction:'');}catch{return '0';}}
 function lockLabel(until){const ms=until-Date.now();if(!Number.isFinite(until)||until<=0)return 'Lock pending';if(ms<=0)return 'Ready to withdraw';const hours=Math.ceil(ms/3600000);return hours<48?'Unlocks in '+hours+' hour'+(hours===1?'':'s'):'Unlocks '+new Date(until).toLocaleString();}
 function relativeTime(ts){const t=typeof ts==='number'?ts:Date.parse(ts);if(!Number.isFinite(t))return '';const d=Date.now()-t;if(d<45000)return 'Just now';if(d<3600000)return Math.max(1,Math.floor(d/60000))+'m ago';if(d<86400000)return Math.max(1,Math.floor(d/3600000))+'h ago';if(d<604800000)return Math.max(1,Math.floor(d/86400000))+'d ago';return new Date(t).toLocaleDateString();}
 function winRate(){const n=profile.wins+profile.losses;return n?Math.round(profile.wins/n*100):null;}
 const LEDGER_COPY={token_win:'GAME won in battle',welcome:'Welcome grant',daily_reward:'Daily reward',upgrade:'Creature upgrade',stake:'Battle stake',refund:'Stake refunded',win:'Battle victory',draw_refund:'Draw refund'};
 const LEDGER_ICON={token_win:'crown',welcome:'coin',daily_reward:'coin',upgrade:'forge',stake:'swords',refund:'shield',win:'crown',draw_refund:'shield'};
 function stakeRows(list){const symbol=esc(runtime.contracts.symbol),now=Date.now();return (list||[]).map(p=>{const ready=p.lockUntil<=now,name=CARDS[p.card]?.name||'Creature',amount=formatUnits(p.amountUnits)+' '+symbol;return `<div class="token-position ${ready?'is-ready':'is-locked'}"><span><b>${esc(name)}</b><small>${esc(amount)}</small></span>${ready?`<button class="button primary" data-unstake="${esc(p.id)}">Withdraw</button>`:`<span class="lock-badge">${esc(lockLabel(p.lockUntil))}</span>`}</div>`;}).join('');}
 function stakeCharacter(id){
  const cfg=runtime.contracts,level=tokenState.levels[id],next=Math.min(5,level+1),total=stakeRequirement(id,next),locked=Number(formatUnits(tokenState.locked[id]).replace(/,/g,''))||0,increment=Math.max(0,total-locked),cardPositions=(tokenState.positions||[]).filter(p=>p.card===id),rows=stakeRows(cardPositions);
  modal(`<div class="modal-art">${sprite(id)}</div><span class="eyebrow">${TOKENS[id].symbol} · TOKEN STAKING LEVEL ${level}</span><h2>${level>=5?'Manage '+CARDS[id].name+'.':'Grow '+CARDS[id].name+'.'}</h2><p>Lock the game token to unlock this character's token-arena level. Withdraw after each position's 1-day lock.</p><div class="staking-ladder">${[1,2,3,4,5].map(l=>`<span class="${l===level?'current':''}"><small>LV. ${l}</small><b>${stakeRequirement(id,l).toLocaleString()}</b></span>`).join('')}</div><div class="pot-summary"><span>Currently staked<b>${formatUnits(tokenState.locked[id])} ${esc(cfg.symbol)}</b></span><span>Add for level ${next}<b>${level>=5?'Maxed':increment.toLocaleString()+' '+esc(cfg.symbol)}</b></span></div>${rows?`<h3 class="stake-positions-title">Your positions</h3>${rows}`:''}<p class="fineprint">Minimum new-position lock: ${Math.round(cfg.lockSeconds/86400)} days. Withdraw lives here and on Trainer once a position unlocks.</p><button class="button primary wide" id="prepare-stake" ${!cfg.configured||level>=5?'disabled':''}>${level>=5?'Maximum level':cfg.configured?'Review staking transaction':'Staking opens at token launch'}</button>${!walletAddress?'<button class="text-button wide" data-action="connect-wallet">Connect wallet</button>':''}`,()=>$('#prepare-stake')?.addEventListener('click',async()=>{if(!account||!walletAddress){walletModal();return;}if(currentWallet()!==walletAddress){toast('Reconnect your signed-in wallet, then review staking.');walletModal();return;}const button=$('#prepare-stake');button.disabled=true;try{const proposal=await call('token/stake/prepare',{card:id,actionId:crypto.randomUUID()});reviewTransaction(proposal,async()=>{await loadTokenState();page='forge';clearModal();renderPage();toast(CARDS[id].name+' reached token level '+tokenState.levels[id]+'.');});}catch(e){toast(e.message);button.disabled=false;}}));
 }
 const proofs=()=>{try{return JSON.parse(localStorage.getItem('clashlings-token-proofs')||'[]');}catch{return [];}};
 const saveProofs=items=>{try{localStorage.setItem('clashlings-token-proofs',JSON.stringify(items.slice(-20)));}catch{}};
 async function verifyProof(proof){const result=await call('token/intent/'+proof.intentId+'/confirm',{signature:proof.signature});if(result.confirmed)saveProofs(proofs().filter(p=>p.intentId!==proof.intentId));return result;}
 function reviewTransaction(proposal,onSuccess){
  modal(`<span class="eyebrow">REVIEW IN YOUR WALLET</span><h2>${proposal.kind==='stake'?'Stake to level up.':proposal.kind==='refund'?'Reclaim your escrow.':proposal.kind==='unstake'?'Withdraw unlocked stake.':'Lock your battle entry.'}</h2><div class="transaction-amount">${formatUnits(proposal.amountUnits,proposal.decimals)} <small>${esc(proposal.symbol)}</small></div><p>${proposal.kind==='stake'?'Unlock '+CARDS[proposal.card].name+' level '+proposal.targetLevel+'.':proposal.kind==='refund'?'Return your cancelled battle entry to its wallet.':proposal.kind==='unstake'?'Return this unlocked staking position to its wallet.':'The contract holds this entry until the match is settled or refunded.'}</p><div class="wallet-address" title="${esc(proposal.mint)}">Mint ${esc(proposal.mint?.slice(0,8))}…${esc(proposal.mint?.slice(-8))}</div><button class="button primary wide" id="approve-token">Approve with wallet</button><p class="fineprint" id="token-tx-status">Check the mint, amount, network and instructions in your wallet before approving. Solana network fees are separate.</p>`,()=>$('#approve-token').addEventListener('click',async()=>{const button=$('#approve-token');button.disabled=true;try{if(currentWallet()!==walletAddress)throw new Error('Reconnect the signed-in wallet before approving.');const signature=await sendTransaction(proposal),proof={intentId:proposal.intentId,signature,wallet:walletAddress,createdAt:Date.now()};saveProofs([...proofs().filter(p=>p.intentId!==proof.intentId),proof]);let result;for(let attempt=0;attempt<15&&!disposed;attempt++){if($('#token-tx-status'))$('#token-tx-status').textContent='Transaction submitted. Waiting for finalized confirmation…';result=await verifyProof(proof);if(result.confirmed)break;await new Promise(resolve=>setTimeout(resolve,2000));}if(disposed)return;if(result?.confirmed){await onSuccess?.(result);}else{toast('Still confirming. Resume from Trainer → Pending transactions.');clearModal();page='profile';renderPage();}}catch(e){toast(e.message);if(button.isConnected)button.disabled=false;}}));
 }
 async function confirmTransaction(id){const proof=proofs().find(p=>p.intentId===id&&p.wallet===walletAddress);if(!proof)return;try{const result=await verifyProof(proof);if(result.pending){toast('Confirmation is still pending.');return;}await loadTokenState();toast('Transaction finalized.');if(result.cancelled){queueId=null;page='profile';clearModal();renderPage();toast('Room cancelled. Your confirmed entry is refundable.');return;}if(result.matchId&&result.kind==='escrow'){startOnline(result.matchId);return;}renderPage();}catch(e){toast(e.message);}}
 function renderTokenProfile(){
  if(disposed||page!=='profile')return;
  const pending=proofs().filter(p=>p.wallet===walletAddress),positions=tokenState.positions||[],staked=positions.reduce((n,p)=>{try{return n+BigInt(p.amountUnits);}catch{return n;}},0n),symbol=esc(runtime.contracts.symbol),ready=positions.filter(p=>p.lockUntil<=Date.now()).length;
  const chip=$('#profile-wallet-chip');
  if(chip){chip.classList.toggle('is-wallet',!!walletAddress);chip.innerHTML=walletAddress?`${icon('shield')}${esc(walletAddress.slice(0,4)+'…'+walletAddress.slice(-4))}`:`${icon('shield')}No wallet`;}
  const stakes=$('#token-stakes');
  if(stakes)stakes.innerHTML=`<span class="eyebrow">GAME TOKEN</span><div class="wallet-amount">${icon('forge')}<h2>${formatUnits(staked.toString())}<small>staked ${symbol}</small></h2></div><div class="balance-meta"><span>Positions<b>${positions.length}</b></span><span>Ready to withdraw<b>${ready}</b></span><span>Lock<b>${Math.round((runtime.contracts.lockSeconds||86400)/86400)} day</b></span></div>${positions.length?`<div class="token-position-list">${stakeRows(positions)}</div>`:'<p class="empty-state">No GAME is staked yet. Stake from Upgrades.</p>'}<p class="fineprint">Staking unlocks character levels. Fight earnings live on the leaderboard. Withdraw appears here after each position unlocks.</p><button class="button secondary wide" data-page="forge">Manage staking ${icon('arrow')}</button>`;
  const alerts=$('#profile-alerts');
  if(alerts)alerts.innerHTML=[
   ...pending.map(p=>`<div class="alert-row"><span>Pending transaction<small>${esc(p.signature.slice(0,10))}…</small></span><button class="button secondary" data-proof="${esc(p.intentId)}">Check status</button></div>`),
   ...(tokenState.refunds||[]).map(r=>`<div class="alert-row"><span>Refundable token escrow<small>${r.stake} ${symbol} from a cancelled room</small></span><button class="button primary" data-refund="${esc(r.id)}">Reclaim</button></div>`),
   ...(tokenState.settlements||[]).map(r=>`<div class="alert-row"><span>Token battle ${esc(r.status)}<small>${r.stake} ${symbol}${r.signature?' · '+esc(r.signature.slice(0,10))+'…':''}</small></span></div>`)
  ].join('');
 }
 function profileHTML(){
  const rate=winRate(),earned=profile.tokenEarned||0,levels=(tokenState.levels||[]).reduce((a,b)=>a+b,0);
  return `<div class="hub-page profile-hub"><section class="panel profile-hero"><div class="profile-hero-art">${sprite(1,'profile-sprite')}</div><div class="profile-hero-copy"><span class="eyebrow">${account?'LEAGUE TRAINER':'PRACTICE TRAINER'}</span><h2>${esc(profile.name)}</h2><div class="profile-chips"><span class="status-chip">${icon('coin')}${earned} GAME earned</span><span class="status-chip" id="profile-wallet-chip">${icon('shield')}${walletAddress?esc(walletAddress.slice(0,4)+'…'+walletAddress.slice(-4)):'No wallet'}</span></div><div class="profile-hero-actions"><button class="button secondary" data-action="edit-name">Edit name</button><button class="button ${!account||walletAddress?'secondary':'primary'}" data-action="connect-wallet">${walletAddress?'Manage wallet':'Connect wallet'}</button>${!account?'<button class="button primary" data-action="account">Create trainer</button>':''}</div></div><div class="profile-stat-grid"><span><b>${earned}</b>GAME earned</span><span><b>${profile.wins}</b>Wins</span><span><b>${profile.losses}</b>Losses</span><span><b>${rate==null?'—':rate+'%'}</b>Win rate</span></div><div class="profile-shortcuts"><button data-page="battle">${icon('swords')}Battle</button><button data-page="forge">${icon('forge')}Upgrades</button><button data-page="rewards">${icon('coin')}Rewards</button><button data-page="ranks">${icon('rank')}Ranks</button></div></section><div class="profile-alerts" id="profile-alerts"></div><div class="profile-balances"><section class="panel balance-card is-credits"><span class="eyebrow">FIGHT EARNINGS</span><div class="wallet-amount">${icon('coin')}<h2>${earned.toLocaleString()}<small>GAME won from battles</small></h2></div><div class="balance-meta"><span>Record<b>${profile.wins}–${profile.losses}</b></span><span>Staking levels<b>${levels}</b></span><span>In battle<b>${activeHold?.asset==='token'?activeHold.stake:0}</b></span></div><p class="fineprint">A win pays the rival's GAME entry on-chain and counts that amount here. New trainers start at zero.</p><button class="button primary wide" data-page="battle">Find a token rival ${icon('arrow')}</button></section><section class="panel balance-card is-tokens token-stakes-panel" id="token-stakes"></section></div><div class="profile-feeds"><section class="panel history-panel"><div class="panel-heading"><h3>Battle earnings</h3></div><div id="credit-history" class="feed-list empty-state">${account?'Loading your activity…':'Create an account to track GAME earned from fights.'}</div></section><section class="panel practice-history"><div class="panel-heading"><h3>Practice battles</h3><button class="text-button" data-action="practice">Play ${icon('arrow')}</button></div>${practiceHistory.length?`<div class="feed-list">${practiceHistory.slice(0,6).map(h=>`<div class="history-row match-row"><span class="result-tag ${h.result==='Victory'?'win':''}">${esc(h.result)}</span><span class="history-copy"><b>Sage Bot</b><small>${esc(h.difficulty==='easy'?'Rookie':'Challenger')} · ${esc(relativeTime(h.date))}</small></span></div>`).join('')}</div>`:'<p class="empty-state">No practice battles yet. Warm up against Sage Bot anytime.</p>'}</section></div></div>`;
 }
 function paintLedger(entries){const list=$('#credit-history');if(!list)return;if(!entries.length){list.textContent='No activity yet.';return;}list.classList.remove('empty-state');list.innerHTML=entries.map(e=>`<div class="history-row"><span class="history-icon">${icon(LEDGER_ICON[e.kind]||'coin')}</span><span class="history-copy"><b>${LEDGER_COPY[e.kind]||esc(e.kind)}</b><small>${esc(relativeTime(e.created_at))}</small></span><b class="${e.delta>0?'positive':'negative'}">${e.delta>0?'+':''}${e.delta}</b></div>`).join('');}
 function ranksHTML(){const rate=winRate();return `<div class="hub-page ranks-hub"><section class="panel ranks-hero"><div><span class="eyebrow">THE CLASHLINGS LEAGUE</span><h2>Earn your place.</h2><p>Rank by GAME won from token fights. A win adds your rival's entry. Practice never moves the board.</p><div class="rank-rules"><span>Win the rival's GAME</span><span>Draws earn nothing</span><span>Practice stays off</span></div></div><div class="ranks-you ${account?'':'is-guest'}">${account?`<span class="eyebrow">YOUR STANDING</span><b id="ranks-you-place">—</b><p>${esc(profile.name)}</p><div class="ranks-you-stats"><span>${profile.tokenEarned||0} GAME earned</span><span>${profile.wins}–${profile.losses}${rate==null?'':' · '+rate+'%'}</span></div>`:`<span class="eyebrow">JOIN THE LEAGUE</span><h3>Create a trainer to see rankings.</h3><button class="button primary" data-action="account">Create trainer</button>`}</div></section><div id="ranks-podium" class="ranks-podium" hidden></div><section class="panel ranks-board"><div class="table-heading" ${account?'':'hidden'}><span>Rank</span><span>Trainer</span><span>Record</span><span>GAME earned</span></div><div id="rank-list" class="${account?'empty-state':'ranks-empty'}">${account?'Loading the league…':`<div class="rank-emblem">${icon('crown')}</div><h3>The league is waiting.</h3><p>Create a trainer to see who earned the most GAME in battle. Practice stays off the leaderboard.</p>`}</div></section></div>`;}
 function paintRanks(players){
  const you=players.findIndex(p=>p.name===profile.name),place=$('#ranks-you-place'),podium=$('#ranks-podium'),list=$('#rank-list');
  if(place)place.textContent=you>=0?'#'+(you+1):'Unranked';
  if(podium){const top=players.slice(0,3),medals=['gold','silver','bronze'];if(top.length){podium.hidden=false;podium.innerHTML=top.map((p,i)=>`<article class="podium-card is-${medals[i]} ${p.name===profile.name?'is-you':''}"><span class="podium-place">${['1st','2nd','3rd'][i]}</span><b title="${esc(p.name)}">${esc(p.name)}</b><span class="podium-trophies">${icon('coin')}${p.tokenEarned||0}</span><small>${p.wins}W · ${p.losses}L</small></article>`).join('');}else podium.hidden=true;}
  if(!list)return;
  if(!players.length){list.className='ranks-empty';list.innerHTML=`<div class="rank-emblem">${icon('crown')}</div><h3>The first champion could be you.</h3><p>Win a token battle to take the board. Rank is GAME earned from fights.</p><button class="button primary" data-page="battle">Find a rival</button>`;return;}
  list.classList.remove('empty-state');list.innerHTML=players.map((p,i)=>`<div class="rank-row is-${i+1} ${p.name===profile.name?'is-you':''}"><span><b class="rank-number">${String(i+1).padStart(2,'0')}</b></span><span><b class="trainer-name" title="${esc(p.name)}">${esc(p.name)}</b>${p.name===profile.name?'<span class="you-badge">YOU</span>':''}</span><span class="rank-record">${p.wins}–${p.losses}</span><span class="rank-trophies">${icon('coin')}<b>${p.tokenEarned||0}</b></span></div>`).join('');
 }
 function rewardsHTML(){const earned=profile.tokenEarned||0;return `<div class="rewards-layout rewards-earn"><section class="panel spin-panel"><span class="eyebrow">TOKEN FIGHT REWARDS</span><h2>Win GAME. Climb the board.</h2><p>Lock an equal GAME entry. The winner takes the pot on-chain. That rival's stake is your fight reward and your leaderboard score.</p><div class="wallet-amount">${icon('coin')}<h2>${earned.toLocaleString()}<small>GAME earned from fights</small></h2></div><div class="pot-summary"><span>You keep your entry plus the rival's</span><span>Leaderboard counts net GAME won</span></div><button class="button primary wide" data-page="battle">${icon('swords')}Find a token rival</button><small class="fineprint">No signup grant. Practice never pays GAME. Draws return each entry and earn nothing.</small></section><section class="panel milestone-panel"><span class="eyebrow">HOW YOU EARN</span><h2>Fight. Settle. Rank.</h2><p>Only finalized token battles count. Credit play and daily credit spins are gone.</p><div class="daily-win-count"><b id="daily-wins">${profile.wins}</b><span>WINS<small id="reward-reset">Token arena</small></span></div><div id="milestones" class="milestone-list feed-list empty-state">${account?'Loading fight rewards…':'Create a trainer, then win GAME in battle.'}</div></section></div>`;}
 async function loadRewards(){if(!account)return;try{rewardData=await call('rewards');paintRewards();}catch(e){toast(e.message);}}
