 async function startTokenBattle(code='',friendly=false){if(!ensureAccount())return;if(!walletAddress||currentWallet()!==walletAddress){walletModal();return;}try{const request={stake,code:code||undefined,mode:friendly||code?'friendly':'ranked',actionId:crypto.randomUUID()};let proposal;try{proposal=await call('token/battle',request);}catch(e){if(e.status&&e.status<500)throw e;proposal=await call('token/battle',request);}if(proposal.match){startOnline(proposal.match);return;}queueId=proposal.matchId;activeHold={id:queueId,stake,asset:'token'};reviewTransaction(proposal,async result=>{if(result.cancelled){queueId=null;await loadTokenState();page='profile';clearModal();renderPage();toast('Room cancelled. Your entry is available for refund.');return;}const d=await call('match/'+proposal.matchId);if(d.state)startOnline(proposal.matchId);else showTokenRoom({...d,code:proposal.code});});}catch(e){toast(e.message);}}
 function joinTokenRoom(){modal('<span class="eyebrow">TOKEN ROOM</span><h2>Bring your token squad.</h2><p>Confirm the same entry amount as your rival before joining.</p><form id="token-room-form"><label for="token-room-code">Room code</label><input id="token-room-code" maxlength="6" required><button class="button primary wide">Review entry</button></form>',()=>$('#token-room-form').addEventListener('submit',e=>{e.preventDefault();startTokenBattle($('#token-room-code').value.trim().toUpperCase(),true);}));}
 function showTokenRoom(data){queueId=data.id;modal(`<span class="eyebrow">TOKEN ARENA</span><h2>Waiting for your rival.</h2>${data.code?`<p>Share room <b>${esc(data.code)}</b>, or have them click Find a token rival with <b>${data.stake} ${esc(runtime.contracts.symbol)}</b>.</p>`:`<p>Have your rival click Find a token rival with the same <b>${data.stake} ${esc(runtime.contracts.symbol)}</b> entry.</p>`}<div class="pot-summary"><span>Entry<b>${data.stake} ${esc(runtime.contracts.symbol)}</b></span><span>Winner's pot<b>${data.stake*2} ${esc(runtime.contracts.symbol)}</b></span></div><div class="queue-dots"><i></i><i></i><i></i></div><p class="fineprint">Do not both create rooms. The second trainer joins this one, then deposits the same entry. Cancel makes a confirmed escrow refundable.</p><button class="button secondary wide" data-action="cancel-queue">Cancel room</button>`);clearInterval(queueTimer);queueTimer=setInterval(async()=>{try{const d=await call('match/'+data.id);if(disposed||!queueId)return;if(d.state){clearInterval(queueTimer);queueId=null;startOnline(data.id);}else if(d.status==='cancelled'){clearInterval(queueTimer);queueId=null;clearModal();await loadTokenState();renderPage();toast('Room cancelled. Check Trainer for refundable escrow.');}}catch{}},1400);}

 function help(){modal(`<span class="eyebrow">A FEW LITTLE TRICKS</span><h2>Your first battle.</h2><ol class="how-to"><li><b>Explore the 3D arena.</b><p>Use the camera controls to orbit, zoom, or switch between tactical and cinematic views.</p></li><li><b>Choose a creature.</b><p>Tap one of the four cards in your hand. Each has an elixir cost.</p></li><li><b>Drop it into the arena.</b><p>Tap a blue deployment area, drag a card, or use the left / right lane buttons.</p></li><li><b>Defend and attack.</b><p>Ground creatures cross the bridges. Flying creatures skip the river.</p></li><li><b>Take the tower.</b><p>Destroy a side tower to unlock that enemy lane for deployment. Destroy the central tower to win immediately. When time ends, destroyed towers decide; remaining tower health breaks a tie.</p></li></ol><div class="help-shortcuts"><b>Keyboard</b><span>1–4: choose · ← / →: deploy · P: pause practice</span></div><p class="fineprint">Token battles: both wallets lock equal GAME. The winner takes the pot. A draw refunds both. Leaving an active battle gives the win to your opponent.</p><button class="button primary wide" data-action="close-modal">Got it. Let's battle ${icon('arrow')}</button>`);}
 async function startPractice(){if(playing){toast('You are already in a battle.');return;}if(queueId){toast('Cancel matchmaking first.');return;}if(account)try{await loadTokenState();}catch{}clearModal();online=false;side=0;matchId=null;capturedLanes.clear();selected=-1;paused=false;playing=true;accum=0;const levels=squadLevels('practice');g=newGame({names:[profile.name,'Sage Bot'],decks:[profile.deck,BOT_DECK],levels:[levels,Array(12).fill(1)],seed:Date.now()>>>0});g.market=marketBaseline(marketFrame);page='battle';renderPage();tone(440,.16);$('#arena-status').innerHTML='<i></i>FREE PRACTICE';const boosted=CARDS.filter(c=>profile.deck.includes(c.id)&&(levels[c.id]||1)>(profile.levels[c.id]||1));if(boosted.length)toast('Practice using staking levels: '+boosted.map(c=>c.name).join(', '));window.scrollTo({top:0,behavior:'instant'});}
 let marketSeen=-1,marketPrev=[];
 function marketPulse(m){if(!playing||!m){marketSeen=-1;return;}const seq=m.sequence||0;if(seq===marketSeen)return;const prev=marketPrev,fresh=seq>marketSeen&&seq-marketSeen<=2;marketSeen=seq;marketPrev=m.multipliers.map((v,i)=>m.status[i]==='live'?v:1);if(!fresh||!seq)return;const deck=g.decks?.[side]?.length?g.decks[side]:profile.deck;let best=-1,delta=0;for(const id of new Set(deck)){const d=marketPrev[id]-(prev[id]??1);if(Math.abs(d)>Math.abs(delta)){delta=d;best=id;}}if(best<0||Math.abs(delta)<.01)return;const pct=Math.round((marketPrev[best]-1)*100),up=delta>0;toast(`${up?'📈':'📉'} ${TOKENS[best].symbol} ${up?'pumped':'dipped'}: ${CARDS[best].name} ${up?'is fired up':'feels drained'} (${pct>0?'+':''}${pct}% damage)`);if(up){tone(660,.09);setTimeout(()=>tone(880,.12),90);}else{tone(330,.12);setTimeout(()=>tone(220,.16),110);}}
 function hud(view){const shown=view||g;if(page!=='battle'||!g||!shown)return;marketPulse(shown.market);if(playing)for(const t of g.towers){if(t.p!==side&&!t.king&&t.hp<=0&&!capturedLanes.has(t.id)){capturedLanes.add(t.id);toast((t.x<300?'Left':'Right')+' lane captured. You can deploy across the river.');}}const marketButton=$('#market-info');if(marketButton){const live=shown.market?.status?.some(s=>s==='live')||(!playing&&marketFrame?.prices?.some(p=>p.status==='live'));marketButton.textContent=((shown.market?.source||marketFrame?.source)==='Pyth'?'PYTH':'MARKET')+' · '+(live?'LIVE':'NEUTRAL');}const p=side,ids=g.hand[p],key=ids.join(',')+'/'+Math.floor(g.elixir[p])+'/'+selected+'/'+playing;if(key!==hudKey){hudKey=key;$('#hand').innerHTML=ids.map((id,i)=>card(CARDS[id],g.levels[p][id],`hand-card ${selected===i?'selected':''} ${g.elixir[p]<CARDS[id].cost?'not-ready':''}`,`data-slot="${i}" aria-pressed="${selected===i}"`)).join('');$('#next-sprite').innerHTML=sprite(g.queue[p][0]);}$('#elixir-value').textContent=shown.elixir[p].toFixed(1);$('#elixir-fill').style.width=(shown.elixir[p]*10)+'%';$('#elixir-rate').textContent=shown.time>=ROUND-40?'2× ELIXIR':'ELIXIR';$('#opponent-name').innerHTML=icon('shield')+esc(g.names[1-p]);const remain=Math.max(0,Math.ceil(ROUND-shown.time));$('#timer').textContent=Math.floor(remain/60)+':'+String(remain%60).padStart(2,'0');$('#timer').classList.toggle('urgent',playing&&remain<=30);$('#score').textContent=shown.score[p]+' : '+shown.score[1-p];$('#hand-hint').textContent=playing?(selected>=0?'Tap a blue area to deploy '+CARDS[ids[selected]].name:(pendingCommands.length?'Confirming '+pendingCommands.length+' move'+(pendingCommands.length>1?'s':'')+'…':'Choose a card. Make your move.')):'Your starting hand';}
