 function bindArena(){const canvas=$('#arena');const coords=e=>render?.pick?render.pick(e.clientX,e.clientY):{x:-999,y:-999};canvas.addEventListener('pointermove',e=>pointer=coords(e));canvas.addEventListener('pointerleave',()=>pointer=null);canvas.addEventListener('pointerdown',e=>{pointer=coords(e);if(playing&&selected>=0){e.preventDefault();place(pointer.x,pointer.y);}});$('#hand').addEventListener('pointerdown',e=>{const b=e.target.closest('[data-slot]');if(!b)return;select(+b.dataset.slot);const start={x:e.clientX,y:e.clientY};const moving=event=>pointer=coords(event),up=event=>{document.removeEventListener('pointermove',moving);document.removeEventListener('pointerup',up);document.removeEventListener('pointercancel',cancelDrag);const p=coords(event);const rect=canvas.getBoundingClientRect();if(event.clientX>=rect.left&&event.clientX<=rect.right&&event.clientY>=rect.top&&event.clientY<=rect.bottom&&Math.hypot(event.clientX-start.x,event.clientY-start.y)>12&&p.x>=0&&p.x<=W&&p.y>=0&&p.y<=H)place(p.x,p.y);pointer=null;},cancelDrag=()=>{document.removeEventListener('pointermove',moving);document.removeEventListener('pointerup',up);document.removeEventListener('pointercancel',cancelDrag);pointer=null;};document.addEventListener('pointermove',moving);document.addEventListener('pointerup',up,{once:true});document.addEventListener('pointercancel',cancelDrag,{once:true});});}
