 function ensureAccount(){if(!account){onboarding();return false;}if(playing){toast('Finish your battle first.');return false;}return true;}
 async function cancelQueue(){if(!queueId)return;const id=queueId;try{const d=await call('match/'+id+'/cancel',{});clearInterval(queueTimer);queueTimer=null;queueId=null;activeHold=null;if(d.profile)profile=d.profile;clearModal();renderPage();toast('Room cancelled. Confirmed token escrow can be reclaimed from Trainer.');loadTokenState();}catch(e){toast(e.message);if(e.status===409){queueId=null;clearInterval(queueTimer);startOnline(id);}}}
